    }

    int count = 0;

    // Check for each number if there exists a number that is twice of it
    for (int number : numbers) {
        int doubleValue = number * 2;
        if (countMap.containsKey(doubleValue)) {
            // If the number is zero, we need to ensure there are at least two zeros
            if (number == 0) {
                if (countMap.get(doubleValue) > 1) {
