            } else {
                count++;
                countMap.put(doubleValue, countMap.get(doubleValue) - 1);
                // If the number itself can be doubled to form another number in the list, reduce its count as well
                if (countMap.get(number) > 0 && countMap.containsKey(number) && countMap.get(number * 2) > 0) {
                    countMap.put(number, countMap.get(number) - 1);
