public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    // Initialize the adjacency list
    boolean[][] connected = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 2) continue;
        int from = path[0];
        int to = path[1];
        if (from >= 0 && from < n && to >= 0 && to < n) {
            connected[from][to] = true;
            connected[to][from] = true; // Assuming bidirectional paths
        }
    }

    // BFS to check if there is a path from start to end
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(start[0]);
    visited[start[0]] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == end[0]) {
            return "can be travelled";
        }
        for (int next = 0; next < n; next++) {
            if (connected[current][next] && !visited[next]) {
                queue.offer(next);
                visited[next] = true;
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canTravel = canTravelRecursive(n, start, end, paths, visited);
    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelRecursive(int n, int[] current, int[] end, int[][] paths, boolean[][] visited) {
    if (current[0] == end[0] && current[1] == end[1]) {
        return true;
    }

    visited[current[0]][current[1]] = true;

    for (int[] path : paths) {
        if (path[0] == current[0] && path[1] == current[1]) {
            int nextX = path[2];
            int nextY = path[3];
            if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && !visited[nextX][nextY]) {
                if (canTravelRecursive(n, new int[]{nextX, nextY}, end, paths, visited)) {
                    return true;
                }
            }
        }
    }

    visited[current[0]][current[1]] = false;
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canTravel = dfs(start[0], start[1], end[0], end[1], visited, paths, n);

    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int currentX, int currentY, int endX, int endY, boolean[][] visited, int[][] paths, int n) {
    if (currentX == endX && currentY == endY) {
        return true;
    }

    if (currentX < 0 || currentX >= n || currentY < 0 || currentY >= n || visited[currentX][currentY]) {
        return false;
    }

    visited[currentX][currentY] = true;

    for (int[] path : paths) {
        int nextX = currentX + path[0];
        int nextY = currentY + path[1];

        if (dfs(nextX, nextY, endX, endY, visited, paths, n)) {
            return true;
        }
    }

    visited[currentX][currentY] = false;
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Set<String> pathSet = new HashSet<>();
    for (int[] path : paths) {
        if (path.length == 2) {
            pathSet.add(path[0] + "," + path[1]);
            pathSet.add(path[1] + "," + path[0]); // Assuming paths are bidirectional
        }
    }

    return dfs(start[0], start[1], end[0], end[1], visited, pathSet) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int ex, int ey, boolean[][] visited, Set<String> pathSet) {
    if (x < 0 || x >= visited.length || y < 0 || y >= visited.length || visited[x][y]) {
        return false;
    }

    if (x == ex && y == ey) {
        return true;
    }

    visited[x][y] = true;

    // Explore all possible directions: up, down, left, right
    if (pathSet.contains((x - 1) + "," + y) && dfs(x - 1, y, ex, ey, visited, pathSet)) return true; // up
    if (pathSet.contains((x + 1) + "," + y) && dfs(x + 1, y, ex, ey, visited, pathSet)) return true; // down
    if (pathSet.contains(x + "," + (y - 1)) && dfs(x, y - 1, ex, ey, visited, pathSet)) return true; // left
    if (pathSet.contains(x + "," + (y + 1)) && dfs(x, y + 1, ex, ey, visited, pathSet)) return true; // right

    visited[x][y] = false; // backtrack

    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Set<String> pathSet = new HashSet<>();
    for (int[] path : paths) {
        pathSet.add(path[0] + "," + path[1]);
        pathSet.add(path[1] + "," + path[0]);
    }

    return canTravel(n, start[0], start[1], end[0], end[1], visited, pathSet) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int x, int y, int endX, int endY, boolean[][] visited, Set<String> pathSet) {
    if (x == endX && y == endY) {
        return true;
    }

    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }

    visited[x][y] = true;

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    for (int[] dir : directions) {
        int newX = x + dir[0];
        int newY = y + dir[1];
        if (pathSet.contains(x + "," + y + "-" + newX + "," + newY) && canTravel(n, newX, newY, endX, endY, visited, pathSet)) {
            return true;
        }
    }

    visited[x][y] = false;
    return false;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "Invalid input";
    }

    int commonCount = 0;
    int lengthSum = word1.length() + word2.length();

    boolean[] used = new boolean[word2.length()];

    for (int i = 0; i < word1.length(); i++) {
        char c1 = word1.charAt(i);
        for (int j = 0; j < word2.length(); j++) {
            if (!used[j] && word2.charAt(j) == c1) {
                commonCount++;
                used[j] = true;
                break;
            }
        }
    }

    if (lengthSum == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(commonCount, lengthSum);
    int numerator = commonCount / gcd;
    int denominator = lengthSum / gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + (denominator == 1 ? numerator : numerator + "/" + denominator);
}

