public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                if (!dp[i][j][k] && k >= nums[i - 1]) {
                    dp[i][j][k] = dp[i - 1][j - 1][k - nums[i - 1]];
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (sum * j % n == 0 && dp[n][j][sum * j / n]) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // We will use a boolean DP array to store whether a certain sum with a certain count is possible
    boolean[][] dp = new boolean[n / 2 + 1][totalSum + 1];
    dp[0][0] = true;

    // Precompute prefix sums for optimization
    int[] prefixSum = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        prefixSum[i] = prefixSum[i - 1] + nums[i - 1];
    }

    // Iterate backwards to avoid overwriting in the DP array
    for (int count = 1; count <= n / 2; count++) {
        for (int sum = 0; sum <= totalSum; sum++) {
            for (int i = 0; i < n; i++) {
                if (sum >= nums[i] && dp[count - 1][sum - nums[i]]) {
                    int totalRemaining = prefixSum[n] - prefixSum[i + 1];
                    int countRemaining = n - 1 - i;
                    if (totalSum * countRemaining == totalRemaining * count) {
                        return true;
                    }
                    dp[count][sum] = true;
                    break;
                }
            }
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
