    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 0; i < n; i++) {
        for (int j = Math.min(i + 1, n / 2); j > 0; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[j - 1][i][k]) {
                    dp[j][i + 1][k + nums[i]] = true;
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (sum * j % n == 0 && dp[j][n][sum * j / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
