    for (int i = 1; i <= n; i++) {
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[i - 1][j][k]) {
                    dp[i][j][k] = true;
                }
                int num = nums[i - 1];
                if (k + num <= sum) {
                    dp[i][j][k + num] = dp[i][j][k + num] || dp[i - 1][j - 1][k];
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[n][i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

