public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<Integer> seen = new HashSet<>();
    int allOne = (1 << k) - 1;
    int value = 0;

    for (int i = 0; i < s.length(); i++) {
        // Add the current bit to the value
        value = (value << 1) & allOne | (s.charAt(i) - '0');

        // Only add to the set once we have a substring of length k
        if (i >= k - 1) {
            seen.add(value);
        }
    }

    return seen.size() == 1 << k;
}

boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k || k < 1) {
        return false;
    }

    int totalPossibleSubstrings = 1 << k; // 2^k
    boolean[] foundSubstrings = new boolean[totalPossibleSubstrings];
    int currentNumber = 0;
    int hashMask = totalPossibleSubstrings - 1; // 2^k - 1

    for (int i = 0; i < s.length(); i++) {
        // Move the window: remove the leftmost bit and add the new bit
        currentNumber = (currentNumber << 1) & hashMask | (s.charAt(i) - '0');

        // We only start recording once we have a full window of size k
        if (i >= k - 1) {
            if (!foundSubstrings[currentNumber]) {
                foundSubstrings[currentNumber] = true;
                totalPossibleSubstrings--;

                if (totalPossibleSubstrings == 0) {
                    return true;
                }
            }
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) {
        return false;
    }

    int totalSubstrings = 1 << k; // 2^k
    boolean[] found = new boolean[totalSubstrings];

    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        int index = Integer.parseInt(substring, 2);
        found[index] = true;
    }

    for (boolean b : found) {
        if (!b) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0 || k > s.length()) {
        return false;
    }

    int totalPossibleCodes = 1 << k; // 2^k
    boolean[] found = new boolean[totalPossibleCodes];

    for (int i = 0; i <= s.length() - k; i++) {
        int index = 0;
        for (int j = 0; j < k; j++) {
            index = (index << 1) + (s.charAt(i + j) - '0');
        }
        found[index] = true;
    }

    for (boolean code : found) {
        if (!code) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }

    int totalPossibleSubstrings = 1 << k; // 2^k
    boolean[] found = new boolean[totalPossibleSubstrings];

    int value = 0;
    int mask = totalPossibleSubstrings - 1; // To keep the last k bits

    for (int i = 0; i < s.length(); i++) {
        // Shift left and add the current bit
        value = (value << 1) & mask;
        value |= s.charAt(i) - '0';

        // Ensure we only start adding once we have a substring of length k
        if (i >= k - 1) {
            found[value] = true;
        }
    }

    for (boolean isFound : found) {
        if (!isFound) {
            return false;
        }
    }

    return true;
}

public int isPrefixOfWord(String sentence, String searchWord) {
    if (sentence == null || searchWord == null || searchWord.isEmpty()) {
        return -1;
    }

    String[] words = sentence.split("\\s+");
    for (int i = 0; i < words.length; i++) {
        if (words[i].startsWith(searchWord)) {
            return i + 1; // Return 1-based index
        }
    }

    return -1;
}

