public int minInsertions(String s) {
    int open = 0; // tracks the number of unmatched '('
    int insertions = 0; // tracks the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else {
            // we encountered a ')'
            if (open > 0) {
                open--; // match it with an existing '('
            } else {
                insertions++; // need to insert a '(' to match this ')'
            }

            // check if we need to handle an unpaired ')'
            // since every closing needs a pair, if next is not ')', insert one
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // skip the next ')', as its pair is already handled
            } else {
                insertions++; // need to insert a ')' to pair this current ')'
            }
        }
    }

    // any remaining '(' need a ')'
    insertions += open * 2;

    return insertions;
}

public int minInsertions(String s) {
    int open = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else {
            if (open > 0) {
                open--;
            } else {
                insertions++;
            }
            if (c == ')' && (c + 1 < s.length() && s.charAt(c + 1) == ')')) {
                c++; // Skip the next ')' as it's a matched pair
            } else {
                insertions++;
            }
        }
    }

    // For each unmatched '(', we need one ')'
    insertions += open * 2;
    return insertions;
}

public int minInsertions(String s) {
    int left = 0; // To count the number of unmatched '('
    int right = 0; // To count the number of needed ')'

    for (char c : s.toCharArray()) {
        if (c == '(') {
            // If there is a need for ')' and we encounter '(', we need to insert a ')'
            if (right > 0) {
                // Insert a ')' to make the pair with the last unmatched '('
                left++;
                right--; // One ')' is used
                // We still need one ')' to pair with the current '('
                right++;
            }
            left++; // Increment the count of '('
        } else if (c == ')') {
            right--; // We found a ')', so decrement the need for ')'
            if (right == -1) {
                // We have one more ')' than needed
                left++; // Insert a '(' to pair with this ')'
                right = 1; // Now we need one more ')'
            }
        }
    }

    return left + right; // The total number of insertions needed
}

public int minInsertions(String s) {
    int left = 0, right = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                left++;
                right--;
            }
            right += 2;
        } else {
            right--;
            if (right == -1) {
                left++;
                right = 1;
            }
        }
    }
    return left + right;
}

public int minInsertions(String s) {
    int open = 0; // To track open parentheses
    int close = 0; // To track the number of insertions needed for close parentheses

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close % 2 == 1) {
                // If we have an odd number of closing brackets, we need to add a closing bracket to balance
                open++;
                close--;
            }
            // Each open bracket needs two closing brackets
            close += 2;
        } else {
            close--;
            if (close == -1) {
                // If we have more closing brackets than needed, we need to add an open bracket
                open++;
                // Reset close to 1 because we effectively add a closing bracket here
                close = 1;
            }
        }
    }

    // The total number of insertions needed is the sum of open and close
    return open + close;
}

public int minOperations(int n) {
    // The target value for all elements to be equal
    int target = n;
    int operations = 0;

    // Calculate the number of operations needed
    for (int i = 0; i < n / 2; i++) {
        int currentValue = (2 * i) + 1;
        operations += target - currentValue;
    }

    return operations;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int operations = 0;
    for (int i = 0; i < n / 2; i++) {
        operations += n - 2 * i - 1;
    }
    return operations;
}

