public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer.");
    }

    // Generate Fibonacci numbers up to k
    int a = 1, b = 1;
    while (b < k) {
        int next = a + b;
        a = b;
        b = next;
    }

    int count = 0;
    while (k > 0) {
        if (b <= k) {
            k -= b;
            count++;
        }
        // Move to the previous Fibonacci number
        int temp = a;
        a = b - a;
        b = temp;
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer.");
    }

    // Generate Fibonacci numbers up to k
    int a = 1, b = 1;
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
    }

    int count = 0;
    while (k > 0) {
        // Use the largest possible Fibonacci number less than or equal to k
        if (a <= k) {
            k -= a;
            count++;
        }
        // Move to the next smaller Fibonacci number
        int temp = a;
        a = b - a;
        b = temp;
    }

    return count;
}

