public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }

    int factorCount = 0;

    for (int i = 1; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            factorCount++;
            if (factorCount == k) {
                return i;
            }
            int pairedFactor = n / i;
            if (pairedFactor != i) {
                // Check if the paired factor is different and count it
                if (factorCount + 1 == k) {
                    return pairedFactor;
                }
            }
        }
    }

    return -1;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }

    int factorCount = 0;

    // Check factors from 1 to sqrt(n)
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factorCount++;
            if (factorCount == k) {
                return i;
            }
            // Check if the paired factor is different and valid
            if (i != n / i) {
                int pairedFactor = n / i;
                if (factorCount + 1 == k) {
                    return pairedFactor;
                }
            }
        }
    }

    return -1; // If there are less than k factors
}

public String makeGood(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    StringBuilder result = new StringBuilder();
    for (char c : s.toCharArray()) {
        if (result.length() > 0 && isValidToRemove(result.charAt(result.length() - 1), c)) {
            result.deleteCharAt(result.length() - 1);
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

