}

private int backtrack(String s, HashSet<String> set) {
    if (s.length() == 0) {
        return 0;
    }
    int maxUnique = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (!set.contains(prefix)) {
            set.add(prefix);
            maxUnique = Math.max(maxUnique, 1 + backtrack(s.substring(i), set));
            set.remove(prefix);
        }
    }
    return maxUnique;
}

