private int backtrack(String s, Set<String> used, int start) {
    if (start == s.length()) {
        return 0;
    }
    int maxUnique = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substr = s.substring(start, end);
        if (!used.contains(substr)) {
            used.add(substr);
            maxUnique = Math.max(maxUnique, 1 + backtrack(s, used, end));
            used.remove(substr);
        }
    }
    return maxUnique;
}

