public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0 || k < n || k > 26 * n) {
        throw new IllegalArgumentException("Invalid input values");
    }

    StringBuilder result = new StringBuilder();
    int remainingValue = k - n;
    int i = 0;

    while (i < n) {
        for (char c = 'a'; c <= 'z'; c++) {
            if (remainingValue - (c - 'a') <= 26 * (n - i - 1)) {
                result.append(c);
                remainingValue -= (c - 'a');
                break;
            }
        }
        i++;
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    // Initialize a char array of size n with 'a'
    char[] result = new char[n];
    Arrays.fill(result, 'a');

    // Subtract the minimum possible value (n) from k
    k -= n;

    // Start filling from the end to make the string lexicographically smallest
    for (int i = n - 1; i >= 0 && k > 0; i--) {
        // Calculate the minimum of k and 25 (since 'z' is 26 - 'a' = 25 more than 'a')
        int diff = Math.min(k, 25);
        // Update the character at position i
        result[i] = (char)('a' + diff);
        // Decrease k by the difference
        k -= diff;
    }

    // Convert the char array to a String and return
    return new String(result);
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();

    // Fill the result with 'a' initially
    for (int i = 0; i < n; i++) {
        result.append('a');
        k -= 1; // 'a' contributes 1 to the total value
    }

    // Now we need to distribute the remaining value (k) over the string
    // Starting from the end to make the string lexicographically smallest
    int i = n - 1;
    while (k > 0) {
        // Calculate the maximum value we can add to the current position
        int add = Math.min(k, 25); // We can add at most 25 to make it 'z'
        result.setCharAt(i, (char) ('a' + add));
        k -= add; // Decrease k by the value we added
        i--; // Move to the previous position
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    if (n < 1 || k < n || k > 26 * n) {
        throw new IllegalArgumentException("Invalid input values");
    }

    StringBuilder result = new StringBuilder();
    int remainingLength = n;
    int remainingValue = k;

    while (remainingLength > 0) {
        int lowerBound = remainingValue - 26 * (remainingLength - 1);
        if (lowerBound <= 1) {
            result.append('a');
            remainingValue -= 1;
        } else {
            char smallestChar = (char) ('a' + lowerBound - 1);
            result.append(smallestChar);
            remainingValue -= lowerBound;
        }
        remainingLength--;
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    if (n < 1 || k < n || k > 26 * n) {
        throw new IllegalArgumentException("Invalid input");
    }

    StringBuilder result = new StringBuilder();
    while (n > 0) {
        int remaining = k - (n - 1);
        if (remaining >= 26) {
            result.append('z');
            k -= 26;
        } else {
            result.append((char) ('a' + remaining - 1));
            k -= remaining;
        }
        n--;
    }

    return result.reverse().toString();
}

