    if (n < 0) {
        throw new IllegalArgumentException("The number should be non-negative.");
    }

    int count = 0;
    for (long m = 1; m <= n; m *= 10) {
        long a = n / m, b = n % m;
        count += (a / 10) * m + Math.min(Math.max(a % 10 - 1, 0) * m + b + 1, m);
    }
    return count;
}

