public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    // Arrays to store the lengths of consecutive 1s in different directions
    int[][] horizontal = new int[rows][cols];
    int[][] vertical = new int[rows][cols];
    int[][] diagonal = new int[rows][cols];
    int[][] antiDiagonal = new int[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                if (j == 0) {
                    horizontal[i][j] = 1;
                } else {
                    horizontal[i][j] = horizontal[i][j - 1] + 1;
                }

                // Vertical
                if (i == 0) {
                    vertical[i][j] = 1;
                } else {
                    vertical[i][j] = vertical[i - 1][j] + 1;
                }

                // Diagonal
                if (i == 0 || j == 0) {
                    diagonal[i][j] = 1;
                } else {
                    diagonal[i][j] = diagonal[i - 1][j - 1] + 1;
                }

                // Anti-diagonal
                if (i == 0 || j == cols - 1) {
                    antiDiagonal[i][j] = 1;
                } else {
                    antiDiagonal[i][j] = antiDiagonal[i - 1][j + 1] + 1;
                }

                // Update the maximum length found
                maxLength = Math.max(maxLength, horizontal[i][j]);
                maxLength = Math.max(maxLength, vertical[i][j]);
                maxLength = Math.max(maxLength, diagonal[i][j]);
                maxLength = Math.max(maxLength, antiDiagonal[i][j]);
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    // Arrays to store the length of continuous 1s
    int[][] horizontal = new int[rows][cols];
    int[][] vertical = new int[rows][cols];
    int[][] diagonal = new int[rows][cols];
    int[][] antiDiagonal = new int[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                // Horizontal line
                horizontal[i][j] = (j > 0) ? horizontal[i][j - 1] + 1 : 1;

                // Vertical line
