private static void findPermutations(int[] A, boolean[] used, int[] current, int pos, int[] count) {
    if (pos == A.length) {
        count[0]++;
        return;
    }
    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            if (pos == 0 || isPerfectSquare(current[pos - 1] + A[i])) {
                used[i] = true;
                current[pos] = A[i];
                findPermutations(A, used, current, pos + 1, count);
                used[i] = false;
            }
            // Skip duplicates
            while (i < A.length - 1 && A[i] == A[i + 1]) i++;
        }
    }
}

