        return;
    }

    Set<Integer> seen = new HashSet<>();
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (current.size() > 0 && seen.contains(A[i]))) continue;

        if (current.isEmpty() || isPerfectSquare(current.get(current.size() - 1) + A[i])) {
            used[i] = true;
