    // Find the smallest digit on the right side of (i-th digit) which is larger than digits[i]
    int x = digits[i];
    int smallest = i + 1;
    for (int j = i + 2; j < len; j++) {
        if (digits[j] > x && digits[j] < digits[smallest]) {
            smallest = j;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[smallest];
    digits[smallest] = temp;

    // Sort the digits after (i-th digit) in ascending order
    Arrays.sort(digits, i + 1, len);

    // Convert the character array to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // This handles the case where the rearranged number is out of integer range
    }
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;

    // Find the rightmost digit that is smaller than the digit next to it
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of (i) that is greater than digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the sequence after the position i
    reverse(digits, i + 1, digits.length - 1);

    // Convert the char array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case of overflow
    }
}

private static void reverse(char[] c, int start, int end) {
    while (start < end) {
        char temp = c[start];
        c[start] = c[end];
        c[end] = temp;
        start++;
        end--;
    }
}

