private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        if (next > n) {
            return;
        }
        dfs(next, n, result);
    }
}

